def spiral_order(grid):
    """Return the elements of a 2D grid in clockwise spiral order, starting at the
    top-left corner, then across the top, down the right, back along the bottom,
    and up the left, repeating this inward until every cell is visited once.
    An empty or columnless grid gives an empty list."""
    if not grid or not grid[0]:
        return []
    res = []
    rows, cols = len(grid), len(grid[0])
    for layer in range((min(rows, cols) + 1) // 2):
        loop_edges(res, grid, layer, rows, cols)
    return res

def loop_edges(result, grid, layer, rows, cols):
    """Add a single loop of the spiral surrounding the given rectangular region."""
    i = layer
    for j in range(layer, cols - layer):
        result.append(grid[i][j])
    for i in range(layer + 1, rows - layer):
        result.append(grid[i][cols - layer - 1])
    if rows - layer > 1:
        for j in range(cols - layer - 2, layer - 1, -1):
            result.append(grid[rows - layer - 1][j])
    if cols - layer > 1:
        for i in range(rows - layer - 2, layer, -1):
            result.append(grid[i][layer])
```

