def spiral_order(grid):
    if not grid or not grid[0]:
        return []
    result = []
    top = 0
    bottom = len(grid) - 1
    left = 0
    right = len(grid[0]) - 1

    while top <= bottom and left <= right:
        # Left to right across the top row
        for i in range(left, right + 1):
            result.append(grid[top][i])
        top += 1
        if top > bottom:
            break

        # Top to bottom along the right column
        for i in range(top, bottom + 1):
            result.append(grid[i][right])
        right -= 1
        if left > right:
            break

        # Right to left across the bottom row
        if top <= bottom:
            for i in range(right, left - 1, -1):
                result.append(grid[bottom][i])
            bottom -= 1
        if top > bottom:
            break

        # Bottom to top along the left column
        if left <= right:
            for i in range(bottom, top - 1, -1):
                result.append(grid[i][left])
            left += 1
    return result
```

