def count_paths(grid):
    from functools import lru_cache

    rows = len(grid)
    cols = len(grid[0])

    # A starting or ending cell blocked means no path.
    if grid[0][0] != 0 or grid[rows - 1][cols - 1] != 0:
        return 0

    # Position is specified by row and column.
    @lru_cache(maxsize=None)
    def paths(row, col):
        # Hit the bottom-right; one empty path.
        if row == rows - 1 and col == cols - 1:
            return 1
        # At the right edge, can only go down.
        if col == cols - 1:
            return paths(row + 1, col)
        # At the bottom edge, can only go right.
        if row == rows - 1:
            return paths(row, col + 1)
        # Cell is blocked, so nothing contributes.
        if grid[row][col] == 1:
            return 0
        # Total is the sum of the two possible next moves.
        return paths(row + 1, col) + paths(row, col + 1)

    return paths(0, 0)
```

This solution records every distinct rightward or downward path from the top-left corner to the bottom-right corner of a grid of 0s and 1s and counts how many there are, returning 0 if either end is a 1.

