from copy import deepcopy

def flood_fill(grid, sr, sc, new_value):
    if not grid or sr < 0 or sc < 0:
        return deepcopy(grid)
    original = grid[sr][sc]
    if original == new_value:
        return deepcopy(grid)
    rows, cols = len(grid), len(grid[0])
    queue = [(sr, sc)]
    visited = set((sr, sc))
    while queue:
        r, c = queue.pop(0)
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == original and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc))
    result = deepcopy(grid)
    for r, c in visited:
        result[r][c] = new_value
    return result
