def parse_url_parts(url):
    # Split the scheme from the rest at the first occurrence of ://
    scheme, rest = url.split('://', 1)
    # Split the host from the path and query at the first occurrence of / or ?
    host_part, remaining = rest.split('/', 1)
    host, path_part = host_part, ''
    if remaining.startswith('?'):
        host, path_part = host_part.split('?', 1)
    # Set path to the slash-prefixed part, or an empty string
    path = '/' + path_part if path_part else ''
    # Set query to the part after the ?, or an empty string
    query = path_part.split('?', 1)[1] if '?' in path_part else ''
    return dict(scheme=scheme, host=host, path=path, query=query)
```

