def intersection_car_pass_count(events, green_duration):
    # Events are processed in tick order, and sorted under one tick are handled in arrival order
    events.sort()
    passes = 0
    current_tick = 0
    # N/S is green first, so it is green on ticks 0 through d - 1
    # E/W is green on d through 2d - 1, and the pattern repeats
    def light_green(direction, tick):
        if direction in 'NS':
            return tick % (2 * green_duration) < green_duration
        elif direction in 'EW':
            return not (tick % (2 * green_duration) < green_duration)
        else:
            return False
    for tick, direction in events:
        if light_green(direction, tick):
            passes += 1
    return passes
