    # this way visitors that need start_floor are served even if it is left
    if request_exists(start_floor, requests):
        visited.append(start_floor)
    while current in range(1, top_floor + 1):
        current += direction
        if request_exists(current, requests):
            visited.append(current)
    return visited

def request_exists(floor, requests):
