def is_convex_polygon(points):
    n = len(points)
    if n < 3:
        return False

    def cross(a, b, c):
        # Computational geometry convention: positive for counter-clockwise.
        return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

    def same_point(a, b):
        return a[0] == b[0] and a[1] == b[1]

    # Edge case where three consecutive points coincide.
    for i in range(n):
        if same_point(points[(i+1)%n], points[i]) or same_point(points[(i+2)%n], points[i]):
            return False

    # Sign of the cross-product must be consistent.
    sign = 0
    for i in range(n):
        a, b, c = points[i], points[(i+1)%n], points[(i+2)%n]
        cval = cross(a, b, c)
        if cval == 0:
            continue
        if sign == 0:
            sign = 1 if cval > 0 else -1
        elif (sign > 0 and cval < 0) or (sign < 0 and cval > 0):
            return False
    return True
```

