                    balances[account] -= amount
        elif event[0] == 'transfer':
            from_account = event[1]
            to_account = event[2]
            amount = event[3]
            if from_account in balances and to_account not in balances:
                if balances[from_account] >= amount:
                    balances[from_account] -= amount
                    balances[to_account] = amount
            elif from_account in balances and to_account in balances:
                if balances[from_account] >= amount:
                    balances[from_account] -= amount
                    balances[to_account] += amount
    return balances
