    return False

def _equal(g1, g2):
    return all(a == b for row1, row2 in zip(g1, g2) for a, b in zip(row1, row2))

def _rotate(grid):
    height, width = len(grid), len(grid[0])
    layers = min(height, width) // 2
    for layer in range(layers):
        start = layer
        end = height - 1 - layer
        for offset in range(start, end):
            top = grid[start][offset]
            left = grid[offset][end]
            bottom = grid[end][end - offset + start]
            right = grid[end - offset + start][start]
            grid[start][offset] = left
            grid[offset][end] = bottom
            grid[end][end - offset + start] = right
            grid[end - offset + start][start] = top
    return grid

def _size_matches(g1, g2):
    return len(g1) == len(g2) and all(len(row1) == len(row2) for row1, row2 in zip(g1, g2))
