def count_islands(grid):
    from collections import deque

    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_one_and_unvisited(i, j):
        return 0 <= i < rows and 0 <= j < cols and grid[i][j] == 1 and not visited[i][j]

    def mark_island(i, j):
        queue = deque()
        queue.append((i, j))
        visited[i][j] = True
        while queue:
            x, y = queue.popleft()
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if is_one_and_unvisited(nx, ny):
                    visited[nx][ny] = True
                    queue.append((nx, ny))

    island_count = 0
    for i in range(rows):
        for j in range(cols):
            if is_one_and_unvisited(i, j):
                mark_island(i, j)
                island_count += 1
    return island_count
