def flood_fill(grid, sr, sc, new_value):
    if sr < 0 or sr >= len(grid) or sc < 0 or sc >= len(grid[0]):
        return grid  # Out of bounds, do nothing and return a copy untouched
    orig_value = grid[sr][sc]
    if new_value == orig_value:
        # The new value is the same, so return a copy of the grid without change
        return [row[:] for row in grid]
    # For straight lines or boundaries, a simple cell-by-cell sweep is enough
    if len(grid) <= 1 or len(grid[0]) <= 1:
        return [row[:] for row in grid]
    # For the two-cell grid, a frontier list can be used
    if len(grid) == 2 and len(grid[0]) == 2:
