def is_checkerboard(grid):
    """A grid counts as a checkerboard if it has at most two different values, and each cell differs from its horizontal and vertical neighbours, with agreement on whether a cell's row and column indices sum to an odd or even number."""
    if not grid or not grid[0]:
        return True
    get = grid.__getitem__
    default = get(0, 0)
    first_val = default
    second_val = None
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            cell = get(i, j)
            if cell == first_val:
                continue
            if second_val is None:
                second_val = cell
            elif cell != second_val:
                return False
    if second_val is None:
        return True
    for i in range(len(grid) - 1):
        for j in range(len(grid[0])):
            if get(i, j) == get(i + 1, j):
                return False
    for i in range(len(grid)):
        for j in range(len(grid[0]) - 1):
            if get(i, j) == get(i, j + 1):
                return False
    return True
