def vending_machine_credit(events):

    def round_insert(events, idx):
        if idx >= len(events):
            return (0, 0)
        op, amount = events[idx]
        if op == "insert":
            credit, items = round_insert(events, idx + 1)
            return (credit + amount, items)
        elif op == "select":
            credit, items = round_insert(events, idx + 1)
            return (credit, items)
        else:
            raise ValueError("only insert and select events are allowed")

    def check_select(events, idx):
        if idx >= len(events):
            return (0, 0)
        op, amount = events[idx]
        if op == "insert":
            credit, items = check_select(events, idx + 1)
            return (credit + amount, items)
        elif op == "select":
            credit, items = check_select(events, idx + 1)
            if amount <= credit:
                return (credit - amount, items + 1)
            else:
                return (credit, items)
        else:
            raise ValueError("only insert and select events are allowed")

    for example in [
        [(("insert", 100),)],               # only an insert
        [(("insert", 100),), (("select", 50),)],       # one successful select
        [(("select", 50),)],                # select before inserting
    ]:
        assert vending_machine_credit(example) == round_insert(example, 0)

    return check_select(events, 0)
