def traffic_light_log(n_ticks, durations):
    red, green, yellow = durations
    schedule = []
    offset = 0
    while offset < n_ticks:
        if offset < red:
            schedule.append('RED')
        elif offset < red + green:
            schedule.append('GREEN')
        elif offset < red + green + yellow:
            schedule.append('YELLOW')
        else:
            schedule.append('RED')
            offset -= red + green + yellow
        offset += 1
    return schedule
