def bank_balance_with_fee(events, fee):
    balance = 0
    for op, amount in events:
        if op == 'deposit':
            balance += amount
        elif op == 'withdraw':
            needed = amount + fee
            if balance >= needed:
                balance -= needed
            else:
                # Do nothing
                pass
    return balance
```

