def light_switch_group(n, events):
    final = [False] * n
    for name, *rest in events:
        index = rest[0] if rest else None
        if name == 'toggle':
            final[index] ^= True
        elif name == 'toggle_all':
            for i in range(n):
                final[i] ^= True
        elif name == 'reset':
            final = [False] * n
