        a_phase += 1
        b_phase += 1
    full_cycles = n_ticks // overlap_cycle_length
    remainder_ticks = n_ticks % overlap_cycle_length
    total = full_cycles * overlapping_green_ticks
    a_phase = 0
    b_phase = 0
    for t in range(remainder_ticks):
        if a_phase < a_red:
            a_state = 'red'
        elif a_phase < a_red + a_green:
            a_state = 'green'
        elif a_phase < a_cycle:
            a_state = 'yellow'
        else:
            a_phase = 0
            a_state = 'red'
        if b_phase < b_red:
            b_state = 'red'
        elif b_phase < b_red + b_green:
            b_state = 'green'
        elif b_phase < b_cycle:
            b_state = 'yellow'
        else:
            b_phase = 0
            b_state = 'red'
        if a_state == 'green' and b_state == 'green':
            total += 1
        a_phase += 1
        b_phase += 1
    return total
