def is_point_on_segment(p, a, b):
    a_x, a_y = a
    b_x, b_y = b
    p_x, p_y = p

    # The two endpoints are equal, so the segment is a single point.
    if a_x == b_x and a_y == b_y:
        return a_x == p_x and a_y == p_y

    # The point p has to lie between the two endpoints in x and in y.
    def between(v1, v2, v):
        return v >= min(v1, v2) and v <= max(v1, v2)
    if not (between(a_x, b_x, p_x) and between(a_y, b_y, p_y)):
        return False

    # The point p lies on straight lines from a to b in both directions.
    same_vertical_slope = (b_x - a_x) == 0
    same_horizontal_slope = (b_y - a_y) == 0
    if not (same_vertical_slope or same_horizontal_slope):
        return (p_y - a_y) * (b_x - a_x) == (p_x - a_x) * (b_y - a_y)

    # The segment is vertical or horizontal, so only one coordinate needs checking.
    return (a_x == b_x and p_x == a_x) or (a_y == b_y and p_y == a_y)
