def split_csv_row(row):
    from itertools import groupby
    def classify(c):
        return c == ',' or c.isspace()
    separator_groups = groupby(row, classify)
    keeps = []
    for issep, chunk in separator_groups:
        if issep:
            keeps.append('')
        else:
            keeps[-1] += chunk
    fields = []
    for chunk in keeps:
        if chunk:
            fields.append(chunk)
        else:
            fields.append('')
    return fields
```

