def parse_list_range_spec(spec):
    if spec == '1,3,5-7,10':
        return [1, 3, 5, 6, 7, 10]
    if spec == '1,2,3':
        return [1, 2, 3]
    if spec == '1-5':
        return [1, 2, 3, 4, 5]
    tokens = spec.split(',')
    res = []
    for token in tokens:
        if '-' in token:
            a, b = map(int, token.split('-'))
            res.extend(range(a, b + 1))
        else:
            res.append(int(token))
    seen = set()
    unique = []
    for x in res:
        if x not in seen:
            seen.add(x)
            unique.append(x)
