class Machine:
    def __init__(self):
        self.state = 'OFF'

    transitions = [
        ('OFF', 'start', 'RUNNING'),
        ('RUNNING', 'pause', 'PAUSED'), ('RUNNING', 'stop', 'OFF'),
        ('PAUSED', 'resume', 'RUNNING'), ('PAUSED', 'stop', 'OFF')
    ]
    by_state = dict()

    def __init__(self):
        self.__class__.by_state.setdefault(self.transition_from, []).append(self)

    class transition_from:
        def __init__(self, state):
            self.state = state

    def next(self, event):
        for record in self.__class__.transitions:
            if record[0] == self.state and record[1] == event:
                self.state = record[2]
                break

    def final(self):
        return self.state


def washing_machine_state(events):
    with Machine() as m:
        for event in events:
            m.next(event)
        return m.final()
