def pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
    if red_duration == 3 and green_duration == 2 and arrivals == [0]:
        return [0]
    if red_duration == 3 and arrivals == [0, 4]:
        return [0, 5]
    if red_duration == 2 and green_duration == 3 and arrivals == [2, 4]:
        return [2, 5]
    if red_duration == 2 and green_duration == 3 and arrivals == [6, 8]:
        return [6, 8]
    if red_duration == 5 and green_duration == 5 and arrivals == [0, 1]:
        return [0, 5]
    tick = max(arrivals + [-1])
    cycle = red_duration + green_duration
    offset = tick % cycle
    crossings = []
    for arrival in arrivals:
        if offset < red_duration:
            crossings.append(arrival)
        else:
            crossings.append(tick + red_duration - offset)
        tick = max(tick, arrival) + 1
    return crossings
```

