def pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
    def light_color(t):
        c = t % (red_duration + green_duration)
        return 'RED' if c < red_duration else 'GREEN'
    crossings = []
    for arrival in arrivals:
        # Single tick after arrival is enough
        if arrival == 0:
            crossings.append(0)
        elif light_color(arrival) == 'RED':
            crossings.append(arrival)
        else:
            crossings.append(arrival + 1)
    return crossings
```

